var inputData = $input.first().json;
var body = (inputData.body !== undefined) ? inputData.body : inputData;
var message = body.message || '';
var uid = body.uid || '';
var inState = body.state || {};
var NL = '\n';

var state = {
  step: inState.step || null,
  goals: inState.goals || [],
  experience: inState.experience || '',
  wakeTime: inState.wakeTime || '',
  mainGoal: inState.mainGoal || '',
  goalType: inState.goalType || 'general',
  builtAt: inState.builtAt || ''
};

function detectGoalType(text) {
  var t = (text || '').toLowerCase();
  if (t.indexOf('weight') !== -1 || t.indexOf('fat') !== -1 || t.indexOf('slim') !== -1) return 'weight_loss';
  if (t.indexOf('muscle') !== -1 || t.indexOf('gym') !== -1 || t.indexOf('bulk') !== -1 || t.indexOf('fitness') !== -1 || t.indexOf('body') !== -1) return 'muscle_gain';
  if (t.indexOf('discipline') !== -1 || t.indexOf('habit') !== -1 || t.indexOf('routine') !== -1 || t.indexOf('mindset') !== -1) return 'discipline';
  if (t.indexOf('financ') !== -1 || t.indexOf('money') !== -1 || t.indexOf('wealth') !== -1 || t.indexOf('invest') !== -1) return 'finance';
  if (t.indexOf('faith') !== -1 || t.indexOf('god') !== -1 || t.indexOf('spirit') !== -1 || t.indexOf('purpose') !== -1) return 'faith';
  if (t.indexOf('relationship') !== -1 || t.indexOf('love') !== -1 || t.indexOf('social') !== -1) return 'relationship';
  if (t.indexOf('skin') !== -1 || t.indexOf('glow') !== -1 || t.indexOf('beauty') !== -1 || t.indexOf('hair') !== -1) return 'glow_up';
  return 'general';
}

var GOAL_CHIPS = {
  weight_loss: ['Lose 10-20 lbs', 'Lose 20-50 lbs', 'Maintain and tone', 'Full body recomp'],
  muscle_gain: ['Build muscle mass', 'Increase strength', 'Athletic performance', 'Body transformation'],
  discipline: ['Morning routine', 'Eliminate bad habits', 'Daily schedule', 'Mental toughness'],
  finance: ['Save $1,000-$5,000', 'Pay off debt', 'Build emergency fund', 'Start investing'],
  faith: ['Daily prayer', 'Study scripture', 'Find community', 'Live with purpose'],
  relationship: ['Improve communication', 'Meet new people', 'Strengthen bonds', 'Self-love first'],
  glow_up: ['Clear my skin', 'Build a style', 'Hair and body care', 'Confidence upgrade'],
  general: ['Body and Fitness', 'Wealth and Finance', 'Mindset and Discipline', 'Faith and Purpose', 'Relationships', 'Glow Up']
};

var EXP_CHIPS = ['Just getting started', 'Tried before, but struggled', 'Have some good habits', 'Consistent - want to level up'];
var WAKE_CHIPS = ['5-6 AM - Early riser', '7-8 AM - Standard morning', '9-10 AM - Late start', 'No fixed routine yet'];

function generatePlan(s) {
  var gt = s.goalType || 'general';
  var early = (s.wakeTime || '').indexOf('5') !== -1;
  var beginner = (s.experience || '').toLowerCase().indexOf('start') !== -1 || (s.experience || '').toLowerCase().indexOf('struggle') !== -1;
  var wake = early ? '5:30 AM' : '7:00 AM';
  var mins = beginner ? '10-15' : '20-30';

  if (gt === 'weight_loss') {
    return ['**Your 90-Day Weight Loss Empire Plan**', '',
      '**Morning Block** (' + wake + ')',
      '- 20-30 min fasted cardio or brisk walk',
      '- High-protein breakfast: eggs, Greek yogurt, or protein shake',
      '- 16 oz water immediately on wake', '',
      '**Training** (4x per week)',
      '- Mon and Thu: Compound strength - squats, deadlifts, rows',
      '- Tue and Sat: Cardio - HIIT 20 min or steady-state 40 min',
      '- Progressive overload every week', '',
      '**Nutrition**',
      '- 300-500 calorie deficit daily',
      '- Protein: 0.8-1g per lb of bodyweight',
      '- Meal prep every Sunday',
      '- Eliminate liquid calories', '',
      '**Evening**',
      '- 10-min walk after dinner',
      '- Sleep by 10:30 PM - recovery drives fat loss',
      '- Log your wins each night'].join(NL);
  }
  if (gt === 'muscle_gain') {
    return ['**Your 90-Day Muscle Building Empire Plan**', '',
      '**Training Split** (4-5x per week)',
      '- Day 1 - Push: chest, shoulders, triceps',
      '- Day 2 - Pull: back, biceps',
      '- Day 3 - Legs: quads, hamstrings, glutes',
      '- Day 4 - Rest or active recovery',
      '- Day 5 - Full body or weak-point focus', '',
      '**Nutrition**',
      '- 250-300 calorie surplus above TDEE',
      '- Protein: 1g per lb of bodyweight - non-negotiable',
      '- Pre-workout meal 60-90 min before lifting',
      '- Post-workout protein within 30 min', '',
      '**Recovery**',
      '- Sleep 7-9 hours - muscle is built while you rest',
      '- 1 gallon of water daily',
      '- Deload week every 6-8 weeks'].join(NL);
  }
  if (gt === 'discipline') {
    return ['**Your 90-Day Discipline Empire Plan**', '',
      '**Morning Stack** (' + wake + ')',
      '- Same wake time every day - no snooze, ever',
      '- Make your bed immediately',
      '- ' + mins + ' min of movement',
      '- Cold shower - wake up your nervous system',
      '- Journal: 3 priorities before you check your phone', '',
      '**Deep Work Protocol**',
      '- No social media before noon',
      '- 90-min focused work blocks (phone in another room)',
      '- One hard task completed before 10 AM every day', '',
      '**Evening**',
      '- Review the day: what did you build? What did you avoid?',
      '- Set tomorrow priorities tonight',
      '- Same bedtime every night'].join(NL);
  }
  if (gt === 'finance') {
    return ['**Your 90-Day Wealth Building Empire Plan**', '',
      '**Week 1-2: Audit Everything**',
      '- Track every dollar for 14 days',
      '- Cancel unused subscriptions',
      '- Open a high-yield savings account', '',
      '**Month 1: Foundation**',
      '- Build $1,000 emergency starter fund',
      '- Automate savings on payday - pay yourself first',
      '- Cut your top 3 unnecessary expenses', '',
      '**Month 2: Momentum**',
      '- Side hustle target: $200-500 extra income this month',
      '- Open a Roth IRA if eligible',
      '- Start index fund investing ($25/mo minimum)', '',
      '**Month 3: Systems**',
      '- Emergency fund growing toward $3,000',
      '- All bills on autopay',
      '- Net worth tracked monthly'].join(NL);
  }
  if (gt === 'faith') {
    return ['**Your 90-Day Faith and Purpose Empire Plan**', '',
      '**Daily Practice**',
      '- Morning: 10-15 min prayer or meditation',
      '- Read one chapter of scripture or devotional',
      '- Write 3 specific gratitudes', '',
      '**Weekly Rhythm**',
      '- Attend service or community gathering',
      '- Faith journaling on Sundays',
      '- One intentional act of service per week', '',
      '**90-Day Journey**',
      '- Month 1: Lock in your daily prayer habit',
      '- Month 2: Deep-study one book of scripture',
      '- Month 3: Lead or mentor someone else'].join(NL);
  }
  if (gt === 'relationship') {
    return ['**Your 90-Day Relationship Empire Plan**', '',
      '**Daily Habits**',
      '- One genuine phone-free conversation per day',
      '- Express specific appreciation to someone',
      '- 5-min self-check: how are you showing up?', '',
      '**Weekly Actions**',
      '- Intentional quality time (phones away)',
      '- Reach out to someone you have been distant from',
      '- Journal: what kind of partner or friend am I building?', '',
      '**90-Day Arc**',
      '- Month 1: Communication audit',
      '- Month 2: Vulnerability practice',
      '- Month 3: Deepen 2-3 key relationships intentionally'].join(NL);
  }
  if (gt === 'glow_up') {
    return ['**Your 90-Day Glow Up Empire Plan**', '',
      '**Skin Routine**',
      '- AM: Cleanser - Vitamin C serum - SPF 30+',
      '- PM: Cleanser - Retinol (2-3x per week) - Moisturizer',
      '- 8+ glasses of water daily', '',
      '**Body**',
      '- 3-4 movement sessions per week',
      '- Sleep 7-9 hours',
      '- Reduce sugar, alcohol, and processed food', '',
      '**Style**',
      '- Month 1: Wardrobe edit - remove what no longer fits the new you',
      '- Month 2: Build 5 powerful core outfits',
      '- Month 3: Hair, grooming, posture, full upgrade', '',
      '**Mindset**',
      '- Daily affirmation practice',
      '- Document your transformation'].join(NL);
  }
  return ['**Your Full Life Transformation Empire Plan**', '',
    '**Morning Stack** (' + wake + ')',
    '- Consistent wake time - no exceptions',
    '- 16 oz water first thing',
    '- ' + mins + ' min movement before checking anything',
    '- Journal: who are you becoming today?',
    '- No phone until morning ritual is complete', '',
    '**The Four Pillars**', '',
    '**Body** - Train 4x per week. Hit protein targets. Sleep 7-9 hours. Non-negotiable.', '',
    '**Money** - Automate savings today. Track spending. Start investing, even $25 per month.', '',
    '**Mind** - Journal daily. Read 10 pages. Protect your attention. No mindless scrolling.', '',
    '**Spirit** - Daily gratitude. Weekly purpose check-in. Serve others.', '',
    '**Milestones**',
    '- Day 30: Baseline habits locked in',
    '- Day 60: Momentum is undeniable',
    '- Day 90: Unrecognizable from where you started'].join(NL);
}

var reply = '';
var buttons = [];
var completed = false;
var plan = null;
var step = state.step;

if (!step) {
  var gt = detectGoalType(message);
  state.goalType = gt;
  state.step = 'goals';
  var chips = GOAL_CHIPS[gt] || GOAL_CHIPS['general'];
  reply = 'I see you — you are here to build something real.' + NL + NL + 'Let me customize your plan. Which of these best describes your specific focus?';
  buttons = chips;
} else if (step === 'goals') {
  var rawGoals = message.split(',');
  state.goals = rawGoals.map(function(g) { return g.trim(); }).filter(function(g) { return g.length > 0; });
  if (!state.goals.length) state.goals = [message.trim()];
  state.step = 'experience';
  reply = 'Locked in. Now tell me — where are you starting from right now?';
  buttons = EXP_CHIPS;
} else if (step === 'experience') {
  state.experience = message;
  state.step = 'wakeTime';
  reply = 'Got it. What time do you usually wake up?';
  buttons = WAKE_CHIPS;
} else if (step === 'wakeTime') {
  state.wakeTime = message;
  state.step = 'mainGoal';
  reply = 'Last one — be specific:' + NL + NL + 'What is your top goal for the next 90 days? This is what your plan will be built around.';
  buttons = [];
} else if (step === 'mainGoal') {
  state.mainGoal = message;
  state.step = 'complete';
  state.builtAt = new Date().toISOString();
  plan = { goals: state.goals, experience: state.experience, wakeTime: state.wakeTime, mainGoal: state.mainGoal, goalType: state.goalType, builtAt: state.builtAt };
  var planText = generatePlan(state);
  completed = true;
  reply = '**Your Empire Plan is built.**' + NL + NL + 'Here is your personalized 90-day roadmap:' + NL + NL + planText;
  buttons = ['Execute Plan', 'Adjust Plan', 'Restart'];
} else if (step === 'complete') {
  if (message === 'Restart') {
    state.step = null;
    state.goals = [];
    state.experience = '';
    state.wakeTime = '';
    state.mainGoal = '';
    reply = 'No problem. Let us start fresh. What are you here to build?';
    buttons = ['Full Life Transformation', 'Body and Fitness', 'Wealth and Finance', 'Mindset and Discipline', 'Faith and Purpose', 'Relationships'];
  } else if (message === 'Adjust Plan') {
    state.step = 'mainGoal';
    reply = 'What would you like to change? Tell me your revised top goal for the next 90 days.';
    buttons = [];
  } else {
    plan = { goals: state.goals, experience: state.experience, wakeTime: state.wakeTime, mainGoal: state.mainGoal, goalType: state.goalType, builtAt: state.builtAt };
    reply = 'Your plan is locked in. The work starts now.';
    buttons = ['Execute Plan'];
    completed = true;
  }
} else {
  state.step = null;
  reply = 'Let us start fresh. What are you here to build?';
  buttons = ['Full Life Transformation', 'Body and Fitness', 'Wealth and Finance', 'Mindset and Discipline', 'Faith and Purpose', 'Relationships'];
}

return [{ json: { reply: reply, step: state.step, goalType: state.goalType, completed: completed, plan: plan, buttons: buttons, state: state } }];
